prospects = []
for i, line in enumerate(raw.splitlines(), 1):
    company, pid, role, engagement, geo, email, proof, opening, contribution, application = line.split('|')
    post = posts[pid]
    source = f'https://news.ycombinator.com/item?id={pid}'
    date = post['date'].split('T')[0]
    if i >= 41:
        category = 'Onsite / relocation required'
    elif i in (36,37,38,39,40):
        category = 'Conditional fit'
    elif 'Worldwide' in geo or 'International engineering' in geo or 'EMEA/APAC' in geo:
        category = 'Global / international stated'
    else:
        category = 'Confirm country / hours'
    greeting = {'AiMi':'Vishnu','This Dot Labs':'This Dot hiring team','Catalyst·Wayfare AI':'Catalyst·Wayfare team','Cardog':'Cardog team','Trackerbot':'Trackerbot team','Namespace':'Hannah','Sundream Studio':'Stefan','Quill':'Rishi','Descartes — Finale Inventory':'Jason','Starbridge':'Starbridge hiring team','Search Atlas':'Joao','Puma.tech':'Yuriy','Inferra':'Sasan','BOSS-IQ':'Ahmet','Charly':'Charly team','Uncountable':'Jason','Fazeshift':'Chris'}.get(company, f'{company} hiring team')
    subject = f'HN — {role} — Bilal Kazmi'
    if company == 'Search Atlas': subject = 'HN — React/Next.js + AI engineer — suitable opening?'
    location = 'I am a senior full-stack engineer with 5+ years of experience, based in Islamabad, Pakistan (UTC+5).'
    if category == 'Onsite / relocation required':
        cta = 'Could we have an initial conversation to establish whether my experience and location could fit this opening? I can share my resume and discuss the project in more detail.'
    elif category == 'Global / international stated':
        cta = 'Would you be open to a short conversation about the role? I can share my resume and walk through the relevant work, including the technical tradeoffs.'
    else:
        cta = 'If my experience fits, could you confirm whether this opportunity can include an engineer based in Pakistan and what working-hour overlap you need? I can share my resume and discuss the work in more detail.'
    body = f'Hi {greeting},\n\n{opening}\n\n{location} {proofs[proof]}\n\n{contribution}\n\n{cta}\n\n{signature}'
    notes = []
    if not email: notes.append('No application email published in the reviewed post. Use the linked application route; this email-style draft can be adapted into a cover note. No address was guessed.')
    if company == 'OpenSanctions': notes.append('Employer requests a form and basic facts, with no cover letter. Keep this draft as preparation; do not email it unsolicited.')
    if company == 'Interview Resources': notes.append('Employer requests the careers form and explicitly discourages email; Oct 1 target start has passed. Confirm vacancy, review sample reports yourself, and add your salary expectation before applying.')
    if company == 'Tandem Health': notes.append('Post publishes a questions-only contact and asks not to send applications there. Application route is used instead.')
    if company == 'Search Atlas': notes.append('The advertised Product Engineer vacancy is a PM role. This is an engineering-routing inquiry explicitly invited by the poster, not an application claiming PM experience. ATS is preferred.')
    if company == 'Fredrin': notes.append('Employer asks applicants to try Fredrin. Complete that yourself before applying; the draft does not claim you have tried it.')
    if company == 'BOSS-IQ': notes.append('Partner role, not an ordinary client contract. Salary is unspecified and described as austere, plus equity. Clarify cash compensation and leadership fit first.')
    if category == 'Onsite / relocation required': notes.append('Conditional prospect: user has not confirmed relocation willingness or work authorization. Draft does not assert either.')
    if date.startswith('2026-09'): notes.append('September hiring signal: reconfirm the vacancy before applying. A visible post is not a guarantee that the role remains unfilled.')
    verification = 'Employer-authored hiring post read on 2026-10-05; country/work authorization not independently guaranteed.'
    if company in ('Tether','Enveritas','Railway','This Dot Labs','Cardog'):
        verification += ' Official role/careers page also retrieved on 2026-10-05.'
    prospects.append(dict(number=i,company=company,role=role,engagement=engagement,category=category,location=geo,email=email,source_date=date,source_url=source,application_url=application,contact_basis='Published in employer hiring post' if email else 'Published application route; email not supplied',verification=verification,notes=' '.join(notes),subject=subject,body=body,status='Unsent local draft'))

send_log_path = ROOT/'gmail-send-log-2026-10-05.json'
send_log = json.loads(send_log_path.read_text(encoding='utf-8-sig')) if send_log_path.exists() else []
sent_by_number = {entry['number']:entry for entry in send_log if entry.get('status')=='sent' and entry.get('sent_folder_verified')}
for p in prospects:
    sent = sent_by_number.get(p['number'])
    p['sent_message_id'] = sent.get('sent_message_id','') if sent else ''
    if sent:
        p['status'] = 'Sent via Gmail — 2026-10-05 — verified in Sent mail'
sent_count = len(sent_by_number)
assert len(prospects)==50 and len({p['company'] for p in prospects})==50
for p in prospects:
    if p['email']:
        # Accept explicitly normalized [at]/at spellings only when visible in the source.
        source_text = posts[p['source_url'].split('=')[-1]]['text']
        normalized = re.sub(r'\s*(?:\[at\]| at | @ )\s*', '@', source_text)
        assert p['email'].lower() in normalized.lower(), (p['company'], p['email'])
    assert 'localhost' not in p['body'] and 'attached' not in p['body'].lower()

(ROOT/'prospects.json').write_text(json.dumps(prospects,ensure_ascii=False,indent=2),encoding='utf-8')
fields = ['number','company','role','engagement','category','location','email','source_date','source_url','application_url','contact_basis','verification','notes','status','sent_message_id','subject','body']
