email_count=sum(bool(p['email']) for p in prospects)
intro=f'''# Bilal Kazmi — 50 prospect outreach drafts

Prepared 5 October 2026. Both contract and full-time opportunities are included.

50 unique organizations, {email_count} published email contacts, {50-email_count} application routes without a published application email. {sent_count} emails were sent via Gmail on 5 October 2026 and verified in Sent mail. Remaining entries are local cover-note drafts for application routes. The sent email texts below are retained as a record; do not send them again.

Sources are individual employer-authored September/October 2026 hiring posts; dates are UTC posting dates. These are hiring prospects, not confirmed customers. Source freshness and country eligibility are separate: remote does not automatically mean Pakistan-eligible. Location restrictions, skill gaps, partner compensation, and application preferences are recorded per prospect. September openings should be reconfirmed. No recipient addresses, rates, availability, relocation willingness, visa status, or resume attachments were invented.

Start with the global/international group. Confirm working hours and eligibility before pursuing the conditional and onsite groups. Metrics and background are drawn from your supplied resume. Attach the actual resume only when applying through the employer's stated route.
'''
parts=[intro]
for p in prospects:
    parts.append(f"## {p['number']:02d}. {p['company']}\n\nStatus: {p['status']}\n\nRole: {p['role']}\n\nEngagement: {p['engagement']}\n\nLocation: {p['location']}\n\nTo: {p['email'] or 'No published email — use application route'}\n\nHiring post: [{p['source_date']}]({p['source_url']}) · [Application route]({p['application_url']})\n\nReview notes: {p['notes'] or p['verification']}\n\nSubject: {p['subject']}\n\n{p['body']}\n\n---\n")
(ROOT/'personalized-emails-2026-10-05.md').write_text('\n'.join(parts),encoding='utf-8')

draft_dir=ROOT/'individual-drafts'; draft_dir.mkdir(exist_ok=True)
for p in prospects:
    slug=re.sub(r'[^a-z0-9]+','-',p['company'].lower()).strip('-')
    (draft_dir/f"{p['number']:02d}-{slug}.txt").write_text(f"Status: {p['status']}\nTo: {p['email'] or '[No public email: application route below]'}\nSubject: {p['subject']}\nSource: {p['source_url']}\nApplication: {p['application_url']}\nReview: {p['location']} {p['notes']}\n\n{p['body']}",encoding='utf-8')
    if p['email']:
        msg=EmailMessage(policy=policy.SMTP)
        msg['From']='Bilal Kazmi <bilalkazmi0711@gmail.com>'
        msg['To']=p['email']; msg['Subject']=p['subject']; msg['X-Unsent']='1'
        msg.set_content(p['body'])
        (draft_dir/f"{p['number']:02d}-{slug}.eml").write_bytes(msg.as_bytes())

